shell_commands:
node -e "
const Ajv = require('./node_modules/ajv/lib/ajv.js');
const ajv = new Ajv({strict: false, allErrors: true});
const validate = ajv.compile({type: 'object', properties: {ssn: {type: 'string'}}, required: ['ssn']});
validate({ssn: 123456789});
console.log('errors:', JSON.stringify(validate.errors, null, 2));
console.log('errorsText:', ajv.errorsText(validate.errors));
"

